class _FeedScreenState extends State<FeedScreen> {
  final _scroll = ScrollController();

  @override
  void initState() {
    super.initState();
    _scroll.addListener(_onScroll); // once per State: hot restart to see it
  }

  @override
  void dispose() {
    _scroll.dispose();
    super.dispose();
  }

  void _onScroll() {
    if (_scroll.position.extentAfter < 300) widget.onNearEnd();
  }

  @override
  Widget build(BuildContext context) => ListView.builder(
        controller: _scroll,
        itemBuilder: (context, i) => ListTile(title: Text('Post $i')),
      );
}
